if(new URLSearchParams(location.search).get('video')==='1')document.documentElement.classList.add('video-neutral');
const $=s=>document.querySelector(s);
const state={brief:'We’re launching a customer portal in four weeks. Design and engineering will work in parallel. We need customer feedback each week, a security review, and a clear launch decision.',view:'Board',risk:false,voice:false,memory:false,artifact:false,session:false,role:'manager'};
const routes=[['morning','☀  Morning brief'],['meeting-plan','✦  Your meeting, already organized'],['assistant','✦  In your assistant'],['brief','＋  Start a project'],['risk','◷  Delivery decisions'],['meeting-live','◉  Join the Zoom meeting'],['meeting','▤  Meeting summary'],['room','▣  In the meeting room'],['voice','♫  Talk to your plan'],['learning','♡  What we remember'],['developer','☷  Your work view'],['create','↗  Interview + deep research'],['strategy','◎  Strategy to outcomes']];
$('#concept-nav').innerHTML=routes.map(([r,t])=>`<button data-route="${r}" onclick="go('${r}')">${t}</button>`).join('');
function go(r){location.hash=r}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function head(k,t,s,action=''){return `<div class="eyebrow">${k}</div><div class="page-head"><div><h1>${t}</h1><p class="sub">${s}</p></div>${action}</div>`}
const av=(s,c='')=>`<span class="avatar ${c}">${s}</span>`;
function task(t,who,date,tag=''){return `<div class="task-card"><p>${t}</p><div class="row spread"><span>${av(who)} &nbsp; ${date}</span>${tag?`<span class="tag ${['Review','At risk'].includes(tag)?'amber':'green'}">${tag}</span>`:''}</div></div>`}
const home=()=>head('Sunday, October 18','Good morning, Aditya','Two things need you today. The rest is moving along.',`<select class="role-switch" aria-label="Your role" onchange="state.role=this.value;go('developer')"><option value="manager">Project manager view</option><option value="developer">Developer view</option></select>`)+`<div class="notice"><span>◷</span><div><strong>Let’s keep the portal launch on track</strong><p>Security review and API integration overlap. Two ways to protect the date are ready.</p></div><button onclick="go('risk')">Review options →</button></div><div class="grid two"><section class="card"><div class="row spread"><h2>Needs your judgment <span class="tag gray">2</span></h2><span class="tiny muted">Prioritized for you</span></div><div class="item"><span class="agent-icon">✦</span><div><h3>Starter flow is ready for review</h3><p>A portal flow drafted from your brief and approved design references.</p><span class="tag">Based on 3 sources</span></div><button onclick="go('create')">Review</button></div><div class="item"><span class="agent-icon">↗</span><div><h3>Choose how to handle Sam’s capacity</h3><p>8 hours of security work overlap with the integration milestone.</p><span class="tag amber">Delivery risk</span></div><button onclick="go('risk')">Decide</button></div></section><section class="card"><h2>Moving without you</h2><p class="tiny">Within the scope you approved</p><div class="line"><span><span class="bullet"></span>Draft weekly launch update</span><span class="tag green">Drafting</span></div><div class="line"><span><span class="bullet"></span>Check linked pull requests</span><span class="tag gray">Watching</span></div><div class="line"><span><span class="bullet"></span>Prepare feedback summary</span><span class="tag gray">Queued</span></div><p class="sourceline">Actions and source material stay attached to the project.</p></section></div><div class="grid three spaced"><div class="card"><div class="tiny muted">CUSTOMER PORTAL</div><div class="metric">Oct 30</div><p class="tiny">Target launch · 12 days away</p><div class="progress"><i style="width:62%"></i></div><button class="inline-link" onclick="go('board')">Open project →</button></div><div class="card"><div class="tiny muted">TODAY’S FOCUS</div><div class="metric">2 decisions</div><p class="tiny">Review the flow. Resolve the capacity conflict.</p><button class="inline-link" onclick="go('assistant')">Talk it through →</button></div><div class="card tint"><h3>What are you trying to achieve?</h3><p class="tiny">Bring a brief. We’ll work out a starting plan together.</p><button onclick="go('brief')">Start something new +</button></div></div>`;
const assistant=()=>head('Principles 1 + 2 / Wherever you work','Your assistant. Your work.','Your project, right beside the conversation.')+`<div class="assistant-layout"><section class="chat"><div class="row"><span class="agent-icon">✦</span><h3>Your assistant</h3></div><div class="bubble">What’s the status of project Helix this week?</div><div class="reply">Hello Aditya, here’s the status of your project Helix.<br><br><strong>Overall: needs attention.</strong> Design and customer feedback are on track. API integration is off track because its authentication check is failing. Security review is at risk because Sam is over capacity.<br><br>Two proposed actions: get Sam’s fix plan today, and move the review to Priya. The launch target is October 30.</div><div class="divider"></div><span class="tag green">Asana connected · MCP</span><p class="tiny">Work stays connected to the same project.</p><div class="composer">Ask a follow-up… <span style="float:right">↑</span></div></section><section class="embedded"><div class="row spread"><span class="mini-brand"><span>● ● ●</span> asana</span><span class="tag gray">Embedded project view · concept</span></div><div class="divider"></div><div class="row spread"><h2>Helix</h2><span class="tag amber">Overall: at risk</span></div><p class="tiny">Summary · Launch target Oct 30. Integration and review need attention; design and feedback are moving.</p><div class="rag-strip" aria-label="Red amber green project status"><span class="rag-red">● Red · 1 off track</span><span class="rag-amber">● Amber · 1 at risk</span><span class="rag-green">● Green · 2 on track</span></div><div class="grid three"><div><div class="metric">18 / 29</div><span class="tiny muted">tasks accepted</span></div><div><div class="metric">2</div><span class="tiny muted">delivery risks</span></div><div><div class="metric">2</div><span class="tiny muted">decisions needed</span></div></div><div class="divider"></div><div class="task-row"><span class="check"></span><span>Complete API integration</span>${av('SL')}<span>Oct 22</span></div><div class="task-row"><span class="check"></span><span>Security review</span>${av('SL')}<span class="tag amber">At risk</span></div><div class="task-row"><span class="check"></span><span>Review portal starter flow</span>${av('AV','coral')}<span>Today</span></div><div class="foot-actions"><button onclick="go('board')">Open project</button><button class="primary" onclick="go('risk')">Review delivery risk →</button></div></section></div>`;
const brief=()=>head('Principle 4 / Bring project expertise','Tell us what you’re trying to achieve','Start with the project. We’ll recommend a way to manage it.')+`<section class="form-area"><div class="step">1 &nbsp; Your brief &nbsp; ───── &nbsp; 2 &nbsp; A recommended approach &nbsp; ───── &nbsp; 3 &nbsp; Your workspace</div><div class="card tint"><h2>A little context goes a long way</h2><p class="sub">What are you building, who is involved, and when does it need to happen?</p><label for="brief-input" class="tiny muted">PROJECT BRIEF</label><textarea id="brief-input" class="briefbox">${state.brief}</textarea><input id="brief-file" type="file" accept=".txt" hidden onchange="loadBrief(this)"><button class="upload" onclick="document.getElementById('brief-file').click()">↑ &nbsp; Or upload a text brief (.txt)</button><div class="row spread"><span class="tiny muted">You can change the recommendation.</span><button class="primary" onclick="state.brief=$('#brief-input').value;go('plan')">Recommend an approach →</button></div></div><p class="tiny muted">This demo uses a prepared recommendation for the customer portal example.</p></section>`;
async function loadBrief(el){if(el.files[0]){$('#brief-input').value=await el.files[0].text();toast('Brief loaded locally. No upload or external service used.')}}
const plan=()=>head('Principle 4 / An opinion, with a reason','A Kanban board, with a launch checkpoint','A starting plan for your portal. Make it yours.')+`<div class="recommend"><section class="card"><span class="tag green">Recommended for this brief</span><div class="empty-space"></div><div class="big-icon">▥</div><h2>Keep parallel work moving</h2><p class="sub">Design and engineering will overlap. A board keeps work moving; a launch checkpoint keeps the date in view.</p><ul class="reasons"><li>Work moves continuously across design and development.</li><li>Weekly feedback can add or change tasks.</li><li>A “Ready for review” stage separates output from acceptance.</li><li>A security checkpoint keeps the launch decision explicit.</li></ul><div class="row"><span class="tiny muted">Prefer another view?</span><button onclick="state.view=state.view==='Board'?'List':'Board';render()">Use ${state.view==='Board'?'list':'board'} instead</button></div></section><section class="card tint"><h3>Your starting workspace</h3><div class="line"><span>Project view</span><strong>${state.view==='Board'?'Kanban board':'Task list'}</strong></div><div class="line"><span>Workflow</span><span>To do → In progress → Review</span></div><div class="line"><span>Weekly rhythm</span><span>Customer feedback · Fridays</span></div><div class="line"><span>Key checkpoint</span><span>Security sign-off · Oct 28</span></div><div class="line"><span>Launch decision</span><span>Oct 30 · Aditya</span></div><div class="divider"></div><h3>Suggested first steps</h3><p class="tiny">Confirm scope, draft the portal flow, connect development evidence, and assign the security review.</p><div class="quote-note">“A little structure to get you started. Room to change it as you go.”</div><div class="foot-actions"><button class="primary" onclick="go('board');toast('Sample workspace prepared from your brief')">Use this starting plan →</button></div></section></div>`;
const board=()=>head('Customer portal / Project','A shared plan, with the work attached','People and capabilities work against the same brief, dates, and acceptance criteria.',`<button onclick="go('voice')">◉ &nbsp; Talk to this plan</button>`)+`<div class="row spread"><div class="tabs"><button class="selected">Work</button><button onclick="go('risk')">Risks & decisions</button><button onclick="go('create')">Outputs</button></div><div class="view-toggle"><button class="${state.view==='Board'?'selected':''}" onclick="state.view='Board';render()">Board</button><button class="${state.view==='List'?'selected':''}" onclick="state.view='List';render()">List</button></div></div>${state.view==='Board'?`<div class="board"><section class="column"><h3>To do <span class="muted">${state.meetingPlanApplied?4:3}</span></h3>${task('Run customer feedback session','AK','Oct 23')}${state.meetingPlanApplied?task('Accessibility check','AL','Oct 23','Assigned'):''}${task('Confirm launch checklist','AV','Oct 28')}${task('Draft customer announcement','✦','Oct 26')}</section><section class="column"><h3>In progress <span class="muted">2</span></h3>${task('Complete API integration','SL','Oct 22','At risk')}${task('Prepare starter portal flow','✦','Today','Draft')}</section><section class="column"><h3>Ready for review <span class="muted">2</span></h3>${task('Review authentication requirements','AV','Today','Review')}${task('Approve portal copy','AK','Oct 21','Review')}<button style="width:100%" onclick="go('create')">Review generated starter →</button></section></div>`:`<table class="list-table"><thead><tr><th>Task</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody><tr><td>Complete API integration</td><td>Sam</td><td>Oct 22</td><td>In progress</td></tr><tr><td>Prepare starter portal flow</td><td>Assistant · Aditya accountable</td><td>Today</td><td>Draft</td></tr><tr><td>Review authentication requirements</td><td>Aditya</td><td>Today</td><td>Ready for review</td></tr>${state.meetingPlanApplied?'<tr><td>Accessibility check</td><td>Alex</td><td>Oct 23</td><td>Assigned</td></tr>':''}<tr><td>Security review</td><td>${state.risk?'Priya':'Sam'}</td><td>Oct 23</td><td>At risk</td></tr></tbody></table>`}<div class="foot-actions"><button onclick="go('learning')">Teach a project preference</button><button class="primary" onclick="go('risk')">Review capacity risk →</button></div>`;
const risk=()=>head('Principle 4 / Proactive project expertise',state.risk?'A plan you’ve adjusted':'A risk worth your attention',state.risk?'Priya takes the review. Sam keeps the integration.':'One overlap. Two ways to protect your launch.')+`<div class="risk-layout"><section class="card"><div class="row spread"><h2>${state.risk?'Security review reassigned':'Sam has two overlapping commitments'}</h2><span class="tag ${state.risk?'green':'amber'}">${state.risk?'Resolved in demo':'Capacity conflict'}</span></div><p class="sub">API integration and security review share the same owner during October 21–23.</p><div class="row">${av('SL')}<strong>Sam Lee</strong><span class="tiny muted">· 32 hours available this week</span></div><div class="capacity"><i style="width:${state.risk?'75':'100'}%"></i></div><div class="row spread tiny"><span>${state.risk?'30':'38'} hours planned</span><span class="muted">${state.risk?'2 hours remaining':'6 hours over capacity'}</span></div><div class="evidence"><h3>Why this may affect the launch</h3><p>The security review is a launch dependency. Integration is still in review, and its linked pull request has failing checks.</p><div class="row"><span class="tag gray">Asana assignments</span><span class="tag gray">Linked PR #184</span></div><p class="tiny muted">Sample evidence · last checked 9:10 AM</p></div><p class="tiny">${state.risk?'Priya owns the 8-hour security review. Sam keeps API integration. You remain accountable for the launch decision.':'Capacity is an estimate. This does not prove the milestone will slip; it is a reason to check.'}</p></section><section class="card tint"><h2>${state.risk?'Decision recorded':'Two ways forward'}</h2>${state.risk?`<div class="memory-card remembered"><strong>Move the review, protect the date</strong><p>Security review → Priya<br>Launch target → Oct 30<br>Reason → Resolve overlapping commitments</p></div><button class="primary" onclick="go('board')">Back to the shared plan →</button><p class="tiny muted">Prototype state only. Nobody has been notified.</p>`:`<h3>1. Reassign the security review</h3><p class="tiny">Priya has the required skill and 10 hours available. Keeps the launch target unchanged.</p><button class="primary" onclick="state.risk=true;render();toast('Sample plan updated. Decision recorded.')">Review and apply reassignment</button><div class="divider"></div><h3>2. Keep Sam, move the checkpoint</h3><p class="tiny">Push the review to Oct 26. Leave less room for follow-up fixes.</p><button onclick="toast('Alternative: Oct 26 review, two days for follow-up. No change applied.')">Inspect alternative</button><div class="divider"></div><button class="inline-link" onclick="go('learning')">This overlap is intentional →</button>`}</section></div>`;
const meeting=()=>head('Principle 5 / From conversation to plan','Summary of the Helio Status Update Meeting','Progress, proposed plan updates, and the decisions still needed.',`<span class="meeting-pill">Zoom · Illustrative recording</span>`)+`<div class="meeting-ended-strip"><span>✓ Meeting ended</span><strong>Asana prepared the follow-through.</strong><small>Review the summary, changes and assigned actions below.</small></div><div class="meeting-recording"><span class="recording-play" aria-hidden="true">▶</span><div><strong>Helio · Status update</strong><small>Aditya, Sam, Priya and Alex · Oct 19</small></div><div class="recording-wave" aria-label="Recording waveform">${[10,17,24,13,29,21,12,26,18,30,15,23,10,19,25,14,27,12].map(n=>`<i style="--h:${n}px"></i>`).join('')}</div><span class="recording-time">12:42 / 18:06</span><span class="tag gray">Sample recording · No audio</span></div><div class="meeting-plan-layout"><aside class="meeting-recap"><h2>Meeting summary</h2><div class="conversation-line"><strong>Progress</strong><p>Design is accepted and customer feedback is on track. API integration is 55% complete, with an authentication check still failing.</p></div><div class="conversation-line"><strong>Plan updates</strong><p>Move security review to Priya so Sam can focus on integration. Add an accessibility check for Alex before the review starts.</p></div><div class="conversation-line"><strong>Launch outlook</strong><p>October 30 remains the target. Confirm the fix and review timing before committing to it.</p></div></aside><section class="meeting-gantt-panel"><div class="row spread"><div><h2>Updated plan</h2></div><span class="tag ${state.meetingPlanApplied?'green':'gray'}">${state.meetingPlanApplied?'Reviewed':'2 updates to review'}</span></div><div class="annotated-gantt"><div class="annotated-head"><span>TASK / OWNER</span><div><span>Oct 20</span><span>22</span><span>24</span><span>26</span><span>28</span><span>30</span></div></div><div class="annotated-row"><div class="annotated-name"><strong>API integration</strong><small>Sam · Oct 22</small></div><div class="annotated-track"><span class="annotated-bar bar-coral" style="left:0;width:27%">55%</span></div><div class="gantt-comment unchanged"><span>!</span><p><strong>Still blocked.</strong> PR #184 authentication check is failing.</p></div></div><div class="annotated-row new-row"><div class="annotated-name"><strong>Accessibility check <em>NEW</em></strong><small><s>Not in the plan</s><br><b>Alex · Oct 23</b></small></div><div class="annotated-track"><span class="annotated-bar bar-sage" style="left:27%;width:13%"></span></div><div class="gantt-comment"><span>＋</span><p><strong>Added from the meeting.</strong> Alex checks keyboard navigation and labels before security review.<small>Aditya · 12:42</small></p></div></div><div class="annotated-row changed-row"><div class="annotated-name"><strong>Security review</strong><small><s>Sam</s> → <b>Priya</b> · Oct 23</small></div><div class="annotated-track"><span class="annotated-bar old-owner" style="left:40%;width:18%"></span><span class="annotated-bar bar-lilac" style="left:40%;width:18%"></span></div><div class="gantt-comment"><span>↗</span><p><strong>Owner changed: <s>Sam</s> → Priya.</strong> Priya has capacity. Sam stays on integration; date unchanged.<small>Aditya · 12:41</small></p></div></div><div class="annotated-row"><div class="annotated-name"><strong>Launch decision</strong><small>Aditya · Oct 30</small></div><div class="annotated-track"><span class="gantt-milestone" style="left:92%">◇</span></div><div class="gantt-comment unchanged"><span>◇</span><p><strong>Decision: target stays October 30.</strong> Approve launch after integration and review pass.<small>Team agreement · 12:43</small></p></div></div></div></section></div><section class="meeting-bottom-decisions"><div class="action-list-heading"><div><span class="brief-label">FROM THIS DISCUSSION</span><h2>Action items</h2><p>Three follow-ups. One accountable owner for each.</p></div><span class="tag amber">${3-Object.values(state.meetingTodos||{}).filter(Boolean).length} open</span></div><div class="meeting-todos">${[['priya','Confirm the security review owner','Can Priya take the review and the October 23 handoff?','Priya','PR','Today','Needs confirmation'],['alex','Complete the accessibility check','Check keyboard navigation and labels before security review.','Alex','AL','Oct 23','New task'],['sam','Share the authentication fix plan','Resolve PR #184’s failing check before confirming the launch date.','Sam','SL','Today','Blocking launch']].map(([id,title,detail,owner,initials,due,status])=>`<label class="meeting-action-row ${state.meetingTodos?.[id]?'action-complete':''}"><input type="checkbox" ${state.meetingTodos?.[id]?'checked':''} onchange="state.meetingTodos={...state.meetingTodos,['${id}']:this.checked};render()"><span class="action-copy"><strong>${title}</strong><small>${detail}</small></span><span class="action-owner">${av(initials)} ${owner}</span><span class="action-due">${due}</span><span class="tag ${state.meetingTodos?.[id]?'green':id==='sam'?'amber':'gray'}">${state.meetingTodos?.[id]?'Done':status}</span></label>`).join('')}</div><div class="meeting-signoff"><span>${state.meetingPlanApplied?'✓ Two plan updates signed off in the sample.':'Review the changed owner and new task before updating the plan.'}</span><button class="primary" onclick="${state.meetingPlanApplied?'resetMeetingPlan()':'keepMeetingPlan()'}">${state.meetingPlanApplied?'Undo sample updates':'Sign off two plan updates →'}</button></div></section><p class="meeting-demo-note">Illustrative recording and plan · Checkboxes are local review notes · No live audio or external changes.</p>`;
const room=()=>head('Principle 5 / Voice in the physical room','One shared board. A conversation around it.','Ask a question. Bring the answer into the room.')+`<div class="room-screen"><div class="row spread"><span class="tiny muted">CUSTOMER PORTAL · ROOM DISPLAY</span><span class="tag">Voice example</span></div><div class="empty-space"></div><h2>“Are we still on for October 30?”</h2><p>One dependency needs attention before we can say yes with confidence.</p><div class="room-timeline"><div><span class="tag green">In progress</span><h3 class="spaced">API integration</h3><span class="tiny muted">Oct 22 · Sam</span></div><div><span class="tag amber">Decision needed</span><h3 class="spaced">Security review</h3><span class="tiny muted">Oct 23 · Owner overlap</span></div><div><span class="tag gray">Target</span><h3 class="spaced">Launch decision</h3><span class="tiny muted">Oct 30 · Aditya</span></div></div><div class="row spread"><span class="tiny muted">Based on the plan and linked development checks · sample data</span><button class="primary" onclick="go('risk')">Show the options →</button></div></div><div class="row spread"><p class="sub">People keep talking. The shared display keeps the work and the decision visible.</p><button onclick="go('voice')">See solo voice editing →</button></div>`;
const voice=()=>head('Principle 5 / Voice while working alone','Talk through the change. See the plan respond.','Say what you want to change. We’ll show you first.')+`<div class="voice-layout"><section class="card voice-panel"><div class="row spread"><h3>Talk to your plan</h3><span class="tag gray">Simulated voice</span></div><div class="wave">${[12,25,42,24,53,36,62,28,48,19,34,12].map(n=>`<i style="--h:${n}px"></i>`).join('')}</div><blockquote>“Add an accessibility check before the security review. Ask Alex to own it.”</blockquote><p class="tiny">${state.voice?'Here’s the change. Does it look right?':'Try the voice example. Your microphone stays off.'}</p><div class="foot-actions" style="margin-top:auto">${state.voice?`<button onclick="state.voice=false;render()">Undo preview</button><button class="primary" onclick="toast('Sample accessibility task added. No external changes.');this.textContent='✓ Applied'">Apply change</button>`:`<button class="primary" onclick="state.voice=true;render()">▶ Play voice example</button>`}</div></section><section class="card gantt-plan"><div class="row spread"><div><span class="tiny muted">CUSTOMER PORTAL</span><h2>Launch plan</h2></div><span class="tag ${state.voice?'green':'gray'}">${state.voice?'Proposed change':'Current plan'}</span></div><div class="gantt-table"><div class="gantt-label tiny muted">TASK / OWNER</div><div class="gantt-days"><span>Oct 20</span><span>22</span><span>24</span><span>26</span><span>28</span><span>30</span></div>${[['API integration','Sam',0,27,'lilac'],...(state.voice?[['Accessibility check','Alex',27,13,'sage']]:[]),['Security review',state.risk?'Priya':'Sam',40,18,'peach'],['Launch decision','Aditya',88,12,'lilac']].map(([name,owner,left,width,color])=>`<div class="gantt-label"><strong>${name}</strong><small>${owner}${name==='Accessibility check'?' · New task':''}</small></div><div class="gantt-track"><div class="gantt-bar ${color}" style="left:${left}%;width:${width}%" title="${name}"></div></div>`).join('')}</div><p class="sourceline">${state.voice?'New: accessibility check assigned to Alex, before security review. Launch date stays October 30.':'A shared schedule with owners and dates. Speak to prepare a change.'}</p></section></div>`;
const learning=()=>head('Principle 6 / Learn the reason behind a correction','An exception is useful context','Tell us why. We’ll use it next time.')+`<div class="grid equal"><section class="card"><span class="tag amber">Capacity warning · Sam Lee</span><div class="bubble">This overlap is intentional. Sam is pairing with Priya on the review, so don’t count both tasks as full-time work this week.</div><h2>What should we remember?</h2><div class="memory-card ${state.memory?'remembered':''}"><strong>Pairing changes the capacity estimate</strong><p>For the customer portal this week, treat Sam’s security review as shared pairing time.</p><div class="line"><span>Scope</span><span>This project only</span></div><div class="line"><span>Expires</span><span>Oct 23</span></div><div class="line"><span>Confirmed by</span><span>Aditya</span></div></div><button class="primary" onclick="state.memory=true;render();toast('Project exception saved in this demo')">${state.memory?'✓ Exception remembered':'Remember this exception'}</button></section><section class="card tint"><h2>A little more understanding</h2><p class="sub">We’ll account for pairing. We’ll still flag a failing security check.</p><div class="item"><span>✓</span><div><h3>Explain what changed</h3><p>Use the adjustment when estimating this week’s work.</p></div></div><div class="item"><span>◷</span><div><h3>Ask again when the exception expires</h3><p>Don’t turn one project’s exception into a permanent rule.</p></div></div><div class="item"><span>↗</span><div><h3>Check whether it helped</h3><p>Did the project stay on track? Did the warning return?</p></div></div><button onclick="state.memory=false;render();toast('Exception removed from the sample memory')">Reset exception</button><button class="inline-link" style="margin-left:14px" onclick="go('developer')">See a different work view →</button></section></div>`;
const developer=()=>head('Principle 3 / Dynamic interfaces',state.role==='developer'?'Your next two days, Alex':'The delivery view, Aditya',state.role==='developer'?'The work you can act on, with the evidence and the deadline in view.':'Schedules, dependencies, and decisions across the project.',`<select class="role-switch" aria-label="Work view" onchange="state.role=this.value;render()"><option value="manager" ${state.role==='manager'?'selected':''}>Project manager</option><option value="developer" ${state.role==='developer'?'selected':''}>Developer</option></select>`)+`${state.role==='manager'?`<div class="notice"><div><strong>Launch readiness depends on two pieces of evidence</strong><p>API checks and security sign-off need review before the Oct 30 decision.</p></div><button onclick="go('risk')">Inspect risk →</button></div><div class="grid equal"><section class="card"><h2>Delivery milestones</h2><div class="line"><span>API integration · Oct 22</span><span class="tag amber">Checks failing</span></div><div class="line"><span>Security review · Oct 23</span><span class="tag gray">Pending</span></div><div class="line"><span>Launch decision · Oct 30</span><span class="tag">Aditya</span></div><p class="sourceline">Connected evidence is an input, not a substitute for acceptance.</p></section><section class="card tint"><h2>Questions to resolve</h2><p>Is the review owner confirmed? Are failing checks blocking acceptance? Is the scope still realistic?</p><button onclick="state.role='developer';render()">See what the developer sees →</button></section></div>`:`<div class="banner"><strong>API integration is due in 2 days. The linked checks are still failing.</strong><p>The pull request is open, but the task is not ready to call complete. Review the failure or let Aditya know what changed.</p></div><div class="grid two spaced"><section class="card"><div class="row spread"><h2>Continue API integration</h2><span class="tag amber">Needs attention</span></div><p class="tiny">Customer portal / Engineering / Due Oct 22</p><div class="code">PR #184 · feat/customer-portal-api<br>✓ Type check<br>✓ Unit tests<br>× Integration / authentication callback<br>Review requested · 1 unresolved comment</div><div class="divider"></div><h3>What will count as done?</h3><p class="tiny">Authentication works end to end, checks pass, and the reviewer accepts the change.</p><button class="primary" onclick="go('create')">Prepare a coding handoff →</button><button style="margin-left:8px" onclick="toast('Draft prepared: API integration may slip; authentication callback needs a fix. Nothing sent.')">Draft update for Aditya</button></section><section class="card tint"><h2>Why this is first</h2><p class="tiny">Security review depends on this integration. Your design cleanup task can wait until the callback is fixed.</p><div class="evidence"><strong class="tiny">Signals used</strong><p>Linked pull request, current checks, reviewer comments, and the project dependency.</p></div><button class="inline-link" onclick="go('board')">See the whole plan →</button></section></div>`}`;
function submitInterviewAnswer(){const next=Math.min((state.voiceDefinitionStep||0)+1,3);state.voiceDefinitionStep=next;state.artifact=false;state.researchFinding=false;state.researchQuestion=false;state.researchWorking=true;render();setTimeout(()=>{if(state.voiceDefinitionStep!==next)return;state.researchWorking=false;state.researchFinding=true;state.researchQuestion=true;state.completedResearch={...state.completedResearch,[next]:true};render()},1800)}
function definitionResearch(step){const findings=[null,{gap:'A success target needs a baseline.',query:'Comparing support themes and current response times',finding:'The one-minute target is a useful hypothesis. Distinguish status lookup time from waiting for the team to reply.',follow:'Which part of the wait are we trying to remove?',source:'Sample support log and customer interview notes'},{gap:'Status is only part of the answer.',query:'Checking what customers still need after seeing a status',finding:'The sample notes ask who owns the next step and when an update will arrive. Add those to the draft scope.',follow:'What should the customer know about the next step?',source:'Sample interview notes and support themes'},{gap:'Recovery needs its own acceptance criteria.',query:'Reviewing sign-in recovery and accessibility gaps',finding:'Include sign-in recovery and keyboard access to status, owner and next update. Validate with usability testing.',follow:'How will we test recovery and the keyboard journey?',source:'Sample requirements checklist and usability notes'}];const f=findings[step]||findings[1];return `<aside class="definition-research"><div class="row spread"><span class="voice-mode-label">\u2726 Deep research</span><span class="tag ${state.researchWorking?'amber':state.researchFinding?'green':'gray'}">${state.researchWorking?'Researching automatically':state.researchFinding?'Gap investigated':'Listening for context'}</span></div><h2>${state.researchWorking?'Your answer opened a research thread.':state.researchFinding?f.gap:'Your answer will guide the research.'}</h2><p>${step?'I identified a gap in your answer and started checking the evidence.':'As you answer, I investigate the gaps and bring useful findings back into the interview.'}</p>${step?`<div class="research-trigger"><small>TRIGGERED BY YOUR ANSWER</small><strong>${step===1?'Find their status in under a minute.':step===2?'See where their request stands.':'Make it work with a keyboard and screen reader.'}</strong></div><ol class="research-steps"><li class="done">\u2713 Identify the missing context <small>${f.gap}</small></li><li class="${state.researchWorking?'research-active':'done'}">${state.researchWorking?'\u25cc':'\u2713'} Review relevant evidence <small>${f.query}</small></li><li class="${state.researchFinding?'done':''}">${state.researchFinding?'\u2713':'\u25cc'} Feed the finding back into the interview</li></ol>${state.researchFinding?`<div class="research-finding"><strong>What this adds</strong><p>${f.finding}</p><span class="tag gray">Working hypothesis - validate with customers</span></div><details class="research-evidence"><summary>Inspect the evidence</summary><p><strong>${f.source}</strong></p><p>Fictional material demonstrates the flow. No live browsing or external research took place.</p></details><p class="research-question"><strong>Next question informed by research:</strong> ${f.follow}</p><span class="research-auto-note">\u2713 Brought back into the interview automatically</span>`:'<div class="research-in-progress"><span class="listening-dot"></span>Research in progress. Keep talking; I am checking the gap alongside you.</div>'}`:'<div class="research-waiting"><span>\u2197</span><strong>No extra prompt needed.</strong><p>Submit an answer. Research starts when there is something to clarify.</p></div>'}<small class="research-sample">Simulated deep research - Fictional evidence</small></aside>`;}
const create=()=>{const step=state.voiceDefinitionStep||0;return head('Get some of the work done / Guided definition','Turn the idea into clear requirements.','Helio · Interview + deep research. Better questions, grounded in evidence.')+`<div class="voice-definition-layout"><section class="voice-definition-interviewer"><div class="row spread"><span class="voice-mode-label">◉ Voice mode</span><span class="tiny muted">${step<3?step+1:3} of 3 questions</span></div><div class="voice-definition-question"><span>${step===0?'LET’S CHOOSE A MEASURE':step===1?'LET’S SHAPE THE USER STORY':step===2?'LET’S DEFINE WHAT DONE MEANS':'READY FOR YOUR REVIEW'}</span><h2>${step===0?'How will we know this is working?':step===1?'What should the customer be able to do first?':step===2?'What must work before this is ready to launch?':'Does this capture what you want to build?'}</h2></div><div class="definition-voice-wave" aria-label="Illustrative voice waveform">${[12,21,39,24,52,30,43,17,35,49,27,14,32,19].map(n=>`<i style="--h:${n}px"></i>`).join('')}</div><p class="voice-guidance">${step===0?'What should improve for the customer or the business? We’ll choose a useful metric together.':step===1?'Talk me through the customer’s first useful action. I’ll turn it into a user story.':step===2?'Think about the outcome, error cases and accessibility. I’ll turn those into requirements.':'The metrics, user story and requirements are now drafted. Review them together.'}</p>${step?`<div class="voice-answer-transcript"><span>YOUR VOICE ANSWER · SAMPLE</span><p>${step===1?'“Fewer status-chasing support tickets, and customers finding an update in under a minute.”':step===2?'“They should sign in and see where their request stands, without contacting support.”':'“Show status and next steps. Handle a failed sign-in clearly, and make the whole journey work with a keyboard and screen reader.”'}</p><small>✓ Added to the definition</small></div>`:''}<div class="voice-definition-action"><span class="voice-mic" aria-hidden="true">♩</span><div><strong>${step<3?'Answer in your own words.':'Your starting definition is ready.'}</strong><small>Simulated voice · Microphone off</small></div></div>${step<3?`<button class="primary" onclick="submitInterviewAnswer()">Submit sample voice answer →</button>`:`<div class="row"><button class="primary" onclick="state.artifact=true;render();toast('Sample definition marked ready for review.')">${state.artifact?'✓ Ready for review':'Mark ready for review'}</button><button onclick="state.voiceDefinitionStep=0;state.artifact=false;state.researchFinding=false;state.researchWorking=false;state.researchQuestion=false;state.completedResearch={};render()">Start again</button></div>`}</section><div class="definition-evidence-column">${definitionResearch(step)}<section class="voice-definition-document"><div class="row spread"><h2>Project definition</h2><span class="tag ${step===3?'green':'gray'}">${2+step} of 5 defined</span></div><div class="definition-entry"><div class="definition-entry-label"><strong>Problem statement</strong><span class="definition-filled">✓ Defined</span></div><p>Customers contact support because they cannot see their request’s status or what happens next.</p></div><div class="definition-entry"><div class="definition-entry-label"><strong>Customer cohort</strong><span class="definition-filled">✓ Defined</span></div><p>Existing customers with active requests who currently rely on email updates.</p></div><div class="definition-entry ${step===0?'entry-pending':''}"><div class="definition-entry-label"><strong>Metrics to move</strong><span class="${step?'definition-filled':'definition-pending-label'}">${step?'✓ Drafted from voice':'Pending'}</span></div><p>${step?'Reduce status-chasing support tickets. Help customers find their status in under a minute.':'How will we know this is working?'}</p>${state.completedResearch?.[1]?'<small class="definition-research-added">Research added: establish a baseline; separate lookup time from waiting for a reply.</small>':''}</div><div class="definition-entry ${step===0?'entry-pending':''}"><div class="definition-entry-label"><strong>User story</strong><span class="${step>1?'definition-filled':'definition-pending-label'}">${step>1?'✓ Drafted from voice':'Pending'}</span></div><p>${step>1?'As a customer with an active request, I want to see its current status and next step so I don’t have to contact support.':'What should the customer be able to do first?'}</p>${state.completedResearch?.[2]?'<small class="definition-research-added">Research added: show the owner and the next expected update, alongside status.</small>':''}</div><div class="definition-entry ${step<3?'entry-pending':''}"><div class="definition-entry-label"><strong>Requirements</strong><span class="${step===3?'definition-filled':'definition-pending-label'}">${step===3?'✓ Drafted from voice':'Pending'}</span></div>${step===3?'<ul><li>Show the customer’s request status and next step after sign-in.</li><li>Explain sign-in failures and how to recover.</li><li>Support keyboard navigation and screen-reader labels.</li></ul>':'<p>What must work before this is ready to launch?</p>'}${state.completedResearch?.[3]?'<small class="definition-research-added">Research added: test recovery and keyboard access across the complete journey.</small>':''}</div><p class="definition-source">Problem and cohort prepared from the brief. Interview answers and reviewed evidence shape the three gaps.</p></section></div></div><p class="meeting-demo-note">Interactive interview + deep research concept · Fictional evidence and simulated research stages · No recording or live research connection.</p>`;};
const morning=()=>{const stage=state.morningStage??2;return `<div class="pm-dashboard monitoring-dashboard"><div class="brief-masthead"><span>MONDAY, OCTOBER 19 · 09:20</span><span>PROACTIVE PROJECT MONITORING</span></div><div class="page-head"><div><div class="pm-persona">${av('AV','coral')} FOR ADITYA · PROJECT MANAGER</div><h1>Hello Aditya. Here’s what moved forward.</h1><p class="sub">Helix · October 30 launch target · Monitoring the plan and handling the follow-through.</p></div><button onclick="go('strategy')">Program outcomes ↗</button></div><div class="monitoring-summary"><span class="tag green">2 items on track</span><span class="tag amber">1 blocker escalated</span><span>Last checked 09:20 · <strong>Sam has already replied.</strong></span></div><div class="monitoring-layout"><section class="card morning-timeline"><div class="row spread"><div><div class="brief-label">HELIX · OCT 19–30</div><h2>Your project plan</h2></div><button class="inline-link" onclick="go('board')">Full project ↗</button></div><div class="brief-sequence" aria-label="Morning briefing steps">${[['The plan','◷'],['On track','✓'],['Needs attention','!'],['Action history','↗']].map(([label,icon],i)=>`<button class="${stage===i?'selected':''}" aria-pressed="${stage===i}" onclick="state.morningStage=${i};render()"><span>${icon}</span>${label}</button>`).join('')}</div><div class="brief-gantt"><div class="brief-gantt-head"><span>KEY ITEM / OWNER</span><div><span>Oct 19</span><span>22</span><span>25</span><span>28</span><span>30</span></div></div>${[['Portal design','Maya',0,25,100,'on-schedule','Accepted · ready for engineering'],['Customer feedback','Anika',8,33,65,'on-schedule','Participants confirmed · Oct 23'],['API integration','Sam',0,33,55,'blocked','Failing authentication check · PR #184'],['Security review',state.meetingPlanApplied?'Priya':'Sam',34,25,0,'watch',state.meetingPlanApplied?'Waiting for integration checks':'6 hours over capacity · depends on API'],['Launch decision','Aditya',90,10,0,'target','October 30 · target']].map(([name,owner,left,width,progress,kind,detail])=>{const active=kind==='on-schedule'?stage>=1:stage>=2;return `<div class="brief-gantt-row ${active?'revealed '+kind:''}"><div class="brief-gantt-name"><strong><span class="brief-check">${active?(kind==='on-schedule'?'✓':kind==='target'?'◇':'!'):'·'}</span>${name}</strong><small>${owner} ${active?'· '+(kind==='on-schedule'?'On track':kind==='blocked'?'Off track':kind==='watch'?'At risk':'Target'):''}</small></div><div class="brief-gantt-track"><div class="brief-gantt-bar" style="left:${left}%;width:${width}%"><i style="width:${progress}%"></i><span>${progress?progress+'%':''}</span></div></div>${active?`<p class="brief-row-reason">${detail}</p>`:''}</div>`}).join('')}</div><p class="sourceline">Design and feedback are on track. Integration is blocked; security review depends on the fix.</p><div class="monitoring-next"><strong>One decision still needs you.</strong><p>Priya can take the security review while Sam resolves integration.</p><button onclick="go('risk')">Review the owner change →</button></div></section><aside class="monitoring-actions"><div class="row spread"><span class="brief-label">ALREADY ACTED UPON</span><span class="tag green">Approved monitoring rules</span></div><h2>Handled before you opened this.</h2><p class="monitoring-intro">The blocker was detected, followed up and routed to the right team.</p><ol class="monitoring-history"><li><span class="activity-tick">✓</span><div><small>09:05 · FOLLOW-UP SENT</small><strong>Asked Sam for the fix plan.</strong><p>Included the failing authentication check and the review dependency.</p></div></li><li><span class="activity-tick">✓</span><div><small>09:12 · SAM REPLIED</small><strong>“The callback is blocked by the identity service.”</strong><p>Sam needs platform support before he can confirm the fix timing.</p></div></li><li class="activity-escalated"><span class="activity-tick">↗</span><div><small>09:15 · ESCALATED</small><strong>Nina in Platform now owns the escalation.</strong><p>Context and PR #184 attached. Next check at 10:00; you’ll hear if the launch target changes.</p><span class="tag amber">Waiting on Platform</span></div></li></ol><button onclick="document.getElementById('monitoring-dialog').showModal()">See the conversation →</button><p class="monitoring-rule">Routine follow-ups and escalation run within the team’s approved rules. Scope and owner changes come back for review.</p></aside></div><p class="meeting-demo-note">Fictional monitoring activity and replies · Interactive concept, no live messages sent.</p></div><dialog id="monitoring-dialog"><button class="dialog-close" aria-label="Close conversation" onclick="document.getElementById('monitoring-dialog').close()">×</button><span class="tag green">Activity history · Sample</span><h2>The follow-through, with context.</h2><div class="conversation-line"><strong>Asana → Sam · 09:05</strong><p>PR #184’s authentication check is still failing. What is blocking the fix, and when can we start security review?</p></div><div class="conversation-line"><strong>Sam → Asana · 09:12</strong><p>The callback is blocked by the identity service. I need Platform to check the token configuration before I can estimate the fix.</p></div><div class="conversation-line"><strong>Asana → Nina, Platform · 09:15</strong><p>Escalated with the failed check, Sam’s reply and the launch dependency. Nina is the escalation owner. Next check: 10:00.</p></div><p class="tiny muted">Fictional activity illustrating approved autonomous follow-up.</p></dialog>`;};
const meetingPlan=()=>{const reveal=state.meetingPlanReveal||state.meetingPlanApplied;return `<div class="meeting-magic"><div class="eyebrow">A LITTLE LESS WORK ABOUT WORK</div><div class="page-head"><div><h1>You talked. The plan caught up.</h1><p class="sub">Friday’s check-in, turned into two prepared updates. Ready for your review.</p></div><button onclick="go('morning')">← Your morning brief</button></div><div class="magic-summary"><span>✦</span><div><strong>${state.meetingPlanApplied?'That’s one less thing to organize.':'I turned the meeting into a plan for you.'}</strong><p>${state.meetingPlanApplied?'New task saved. Review reassigned. The meeting stays attached to both.':'I found the decisions, checked the owners, and kept the launch date in view.'}</p></div><span class="tag ${state.meetingPlanApplied?'green':'gray'}">${state.meetingPlanApplied?'Reviewed · Sample plan':'Prepared · Not applied'}</span></div><div class="magic-workspace"><aside class="meeting-source"><div class="brief-label">WHAT YOU SAID</div><div class="source-speaker">${av('AV','coral')} Aditya · Portal check-in</div><p class="decision-invite">Tap a decision. See where it landed.</p><blockquote><button class="spoken-decision ${state.meetingPlanFocus==='review'?'spoken-selected':''}" onclick="revealMeetingDecision('review')">“Move security review to Priya.</button><button class="spoken-decision ${state.meetingPlanFocus==='accessibility'?'spoken-selected':''}" onclick="revealMeetingDecision('accessibility')">Add an accessibility check for Alex before the review.</button><button class="spoken-decision ${state.meetingPlanFocus==='launch'?'spoken-selected':''}" onclick="revealMeetingDecision('launch')">Keep the October 30 launch.”</button></blockquote><div class="source-context"><span>◉</span> Friday, Oct 16 · 10:42 AM<br><small>Illustrative meeting transcript</small></div><div class="source-check"><strong>One thing I haven’t assumed.</strong><p>PR #184 still has a failing authentication check. The launch date remains a target until that passes.</p></div></aside><section class="card magic-plan"><div class="row spread"><div><div class="brief-label">CUSTOMER PORTAL</div><h2>${reveal?'Here’s what I prepared.':'Here’s where we left the plan.'}</h2></div><span class="tag ${reveal?'green':'gray'}">${reveal?'After the meeting':'Before the meeting'}</span></div><div class="magic-gantt"><div class="gantt-label tiny muted">TASK / OWNER</div><div class="gantt-days"><span>Oct 20</span><span>22</span><span>24</span><span>26</span><span>28</span><span>30</span></div><div class="gantt-label"><strong>API integration</strong><small>Sam · Check still failing</small></div><div class="gantt-track"><div class="gantt-bar lilac" style="left:0;width:27%"></div></div>${reveal?`<div class="gantt-label magic-arrive ${state.meetingPlanFocus==='accessibility'?'decision-target':''}"><strong>Accessibility check</strong><small>Alex <span class="new-note">New assignment</span></small></div><div class="gantt-track magic-arrive"><div class="gantt-bar sage" style="left:27%;width:13%"></div></div>`:''}<div class="gantt-label ${reveal&&state.meetingPlanFocus==='review'?'decision-target':''}"><strong>Security review</strong><small>${reveal?'<s>Sam</s> <strong class="changed-owner">→ Priya</strong>':'Sam'}</small></div><div class="gantt-track"><div class="gantt-bar ${reveal?'sage':'peach'}" style="left:40%;width:18%"></div></div><div class="gantt-label ${reveal&&state.meetingPlanFocus==='launch'?'decision-target':''}"><strong>Launch decision</strong><small>Aditya · Oct 30</small></div><div class="gantt-track"><div class="gantt-bar lilac" style="left:88%;width:12%"></div></div></div>${reveal?`<div class="magic-receipt magic-arrive"><div><strong>1 task added</strong><span>Accessibility check · Alex</span></div><div><strong>1 owner changed</strong><span>Security review · Priya</span></div><div><strong>Oct 30 kept</strong><span>Launch target unchanged</span></div></div>`:`<div class="magic-invitation"><span>Three decisions in the conversation.</span><strong>The project shouldn’t need a second round of typing.</strong></div>`}<div class="magic-actions">${reveal?`${state.meetingPlanApplied?'<span class="magic-saved">✓ Kept in your sample plan</span>':'<button class="primary" onclick="keepMeetingPlan()">Keep these two updates →</button>'}<button onclick="resetMeetingPlan()">${state.meetingPlanApplied?'Undo sample updates':'Back to the original'}</button>`:'<button class="primary" onclick="state.meetingPlanReveal=true;render()">✦ Show me what changed</button>'}</div><p class="sourceline">${reveal?'You choose what to keep. Each update links back to the meeting.':'Prepared in the background. A human reviews before the plan changes.'}</p></section></div><p class="tiny muted">Interactive concept · Fictional meeting and project data · No meeting joined or people notified.</p></div>`;};
function revealMeetingDecision(which){state.meetingPlanReveal=true;state.meetingPlanFocus=which;render()}
function keepMeetingPlan(){if(!state.meetingPlanApplied)state.beforeMeetingPlan={risk:state.risk,voice:state.voice};state.risk=true;state.voice=true;state.meetingPlanApplied=true;render();toast('Two updates kept in the sample plan. Nobody notified.')}
function resetMeetingPlan(){if(state.meetingPlanApplied){state.risk=state.beforeMeetingPlan?.risk??false;state.voice=state.beforeMeetingPlan?.voice??false}state.meetingPlanApplied=false;state.meetingPlanReveal=false;state.meetingPlanFocus=null;render()}
const meetingLive=()=>head('Voice / Join the meeting','The conversation becomes the next steps.','A Zoom-style meeting with Asana alongside the team.')+`<div class="zoom-live"><div class="zoom-live-top"><strong>Zoom · Helio status update</strong><span>${state.joinedMeeting?'● Asana has joined':'Waiting for Asana'}</span></div><div class="zoom-live-body"><section class="zoom-call-stage"><div class="zoom-call-tiles">${[['AV','Aditya','Product'],['SL','Sam','Engineering'],['PR','Priya','Security'],['AL','Alex','Experience']].map(([initials,name,role],i)=>`<div class="zoom-person tile-${i}"><span>${initials}</span><small>${name} · ${role}</small></div>`).join('')}</div><div class="zoom-live-caption"><span>LIVE DISCUSSION · SAMPLE</span><p>“Move the review to Priya. Add an accessibility check for Alex. Keep October 30 as the target.”</p></div><div class="zoom-call-controls"><span>♩ Mute</span><span>▣ Video</span><span>☷ Participants</span><span>↥ Share</span><span class="zoom-leave">Leave</span></div></section><aside class="zoom-asana-panel"><div class="row spread"><strong>✦ Asana</strong><span class="tag ${state.joinedMeeting?'green':'gray'}">${state.joinedMeeting?'Joined':'Ready to join'}</span></div>${state.joinedMeeting?`<div class="meeting-listening"><span class="listening-dot"></span> Listening and taking notes</div><h2>I’m keeping track.</h2><p class="tiny">Keep talking. The summary and plan changes will be ready when you finish.</p><div class="live-meeting-notes"><span class="brief-label">CAPTURED FROM THE DISCUSSION</span><p><strong>Review owner</strong><br>Move security review from Sam to Priya.</p><p><strong>New work</strong><br>Add an accessibility check for Alex.</p><p><strong>Launch target</strong><br>Keep October 30; confirm the integration fix.</p></div><div class="zoom-plan-proposal"><strong>Ready when the meeting ends</strong><p>Summary · Annotated plan changes · Assigned action items</p><button class="primary" onclick="go('meeting')">End sample meeting and review →</button></div>`:`<h2>Bring the plan into the conversation.</h2><p>Asana follows the discussion, prepares to-dos and proposes plan changes for sign-off.</p><button class="primary" onclick="state.joinedMeeting=true;render()">Join this sample meeting →</button>`}</aside></div></div><p class="meeting-demo-note">Illustrative Zoom-style UI · No live call, recording or participant notification · Fictional participants and conversation.</p>`;
const strategy=()=>{const active=state.strategyMetric||'support';const metrics={support:{name:'Status-chasing tickets',value:'−18%',target:'−30%',status:'Behind target',reason:'Customers still cannot see who owns the next step. Delivery is moving, but that gap may limit the outcome.',project:'Customer portal',task:'Show owner and next expected update',effort:'240 h',source:'Support themes + portal adoption',next:'Validate the next-step requirement with customers.'},adoption:{name:'Portal adoption',value:'42%',target:'60%',status:'Needs attention',reason:'Customers with older requests still receive email-only updates. Adoption is concentrated in newly created requests.',project:'Customer onboarding',task:'Invite existing active customers',effort:'100 h',source:'Sample product events + cohort breakdown',next:'Pilot invitations with the existing-customer cohort.'},cycle:{name:'Time to find an update',value:'74 sec',target:'<60 sec',status:'Near target',reason:'Sign-in and request lookup account for most of the remaining time. The status screen itself is not the only bottleneck.',project:'Portal experience',task:'Simplify sign-in recovery',effort:'80 h',source:'Sample usability sessions',next:'Test sign-in recovery before adding more dashboard features.'}};const m=metrics[active];return head('Strategy / Program health','Is the work moving the outcome?','Helio program · Strategy, goals, delivery and effort in one view.')+`<section class="program-objective"><div><span class="brief-label">STRATEGIC OBJECTIVE · Q4</span><h2>Help customers get answers without chasing support.</h2><p>Reduce avoidable contacts while making each request’s owner and next step clear.</p></div><span class="tag amber">Overall · Needs attention</span></section><div class="strategy-metrics">${Object.entries(metrics).map(([key,x])=>`<button class="strategy-metric ${key===active?'metric-selected':''}" onclick="state.strategyMetric='${key}';render()"><span>${x.name}</span><strong>${x.value}</strong><small>Goal ${x.target} · ${x.status}</small><div class="metric-mini-bars" aria-hidden="true">${[35,46,42,60,68,75].map((n,i)=>`<i style="height:${Math.round(n/2)}px"></i>`).join('')}</div></button>`).join('')}<div class="strategy-effort"><span>PROGRAM EFFORT</span><strong>640 h</strong><p>420 h on outcome-linked work<br>220 h on platform and maintenance</p><small>Illustrative tracked + estimated effort</small></div></div><div class="strategy-detail-layout"><section class="card strategy-reasoning"><div class="row spread"><h2>Why this metric is ${active==='cycle'?'near':'behind'} target</h2><span class="tag gray">Evidence review</span></div><p class="strategy-conclusion">${m.reason}</p><div class="strategy-causal"><div><small>STRATEGY</small><strong>Fewer avoidable contacts</strong></div><span>↓</span><div><small>PROJECT</small><strong>${m.project}</strong></div><span>↓</span><div><small>WORK TO CHECK</small><strong>${m.task}</strong><p>${m.effort} related project effort · Outcome still to validate</p></div></div><div class="research-finding"><strong>Recommended next step</strong><p>${m.next}</p><button onclick="go('create')">Explore through interview + deep research →</button></div><details><summary>How this conclusion was formed</summary><p>Compare the goal with the current metric, inspect the cohort, then trace related delivery and effort. ${m.source} informs this hypothesis; task completion alone does not establish causation.</p></details></section><section class="card strategy-work"><h2>Where the effort is going</h2><p class="tiny">Projects supporting the same objective</p>${[['Customer portal','240 h','62% delivered','Outcome gap remains'],['Customer onboarding','100 h','45% delivered','Existing cohort missing'],['Portal experience','80 h','70% delivered','Sign-in friction'],['Platform + maintenance','220 h','Supporting work','Indirect contribution']].map(([name,hours,progress,note])=>`<div class="effort-row"><div><strong>${name}</strong><small>${progress} · ${note}</small></div><b>${hours}</b></div>`).join('')}<div class="strategy-effort-note"><strong>Delivery and impact are different measures.</strong><p>The portal is 62% delivered. Support contacts are down 18% against a 30% goal. Check the missing customer behavior before adding more scope.</p></div></section></div><p class="meeting-demo-note">Illustrative program, metrics, effort and reasoning · No live analytics or causal claims.</p>`;};
const pages={'meeting-live':meetingLive,'meeting-plan':meetingPlan,morning,home,assistant,brief,plan,board,risk,meeting,room,voice,learning,developer,create,strategy};
function render(){let r=location.hash.slice(1)||'home';if(!pages[r])r='home';$('#main').innerHTML=pages[r]();document.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('active',el.dataset.route===r));document.querySelectorAll('#main .card > h2').forEach((h,i)=>{const icon=document.createElement('span');icon.className='panel-icon icon-'+(i%3);icon.textContent=['✦','◷','✓'][i%3];h.prepend(icon)});document.title=`Asana concept · ${r}`;window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
